import{_ as a,o as t,c as n,a0 as i}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Why a Local Bank in the Destination Country Is Required","description":"","frontmatter":{},"headers":[],"relativePath":"business/local-bank-requirement.md","filePath":"business/local-bank-requirement.md"}'),r={name:"business/local-bank-requirement.md"};function o(s,e,l,c,h,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="why-a-local-bank-in-the-destination-country-is-required" tabindex="-1">Why a Local Bank in the Destination Country Is Required <a class="header-anchor" href="#why-a-local-bank-in-the-destination-country-is-required" aria-label="Permalink to &quot;Why a Local Bank in the Destination Country Is Required&quot;">​</a></h1><p>Stablecoin settlement solves the <em>movement</em> of value across borders. It does not solve the <em>last mile</em>: converting that value into spendable local currency in the recipient&#39;s hands. That step requires a licensed local bank or payout partner in the destination country, for reasons that are structural, not incidental.</p><h2 id="why-this-cannot-be-designed-around" tabindex="-1">Why this cannot be designed around <a class="header-anchor" href="#why-this-cannot-be-designed-around" aria-label="Permalink to &quot;Why this cannot be designed around&quot;">​</a></h2><ol><li><strong>Local currency issuance and delivery is a banking function.</strong> Only a locally licensed bank (or an e-money institution operating under local law) can credit a recipient&#39;s bank account in local currency, or hand over cash through a regulated network.</li><li><strong>Compliance is jurisdiction-specific.</strong> Verification of Payee, sanctions screening, and AML obligations at the point of payout are governed by the destination country&#39;s regulator, not by us or by any upstream stablecoin infrastructure provider.</li><li><strong>This project never becomes the payout entity.</strong> Per <a href="./../legal/why-this-is-legal.html">Why This Is Legal</a>, the entire non-custodial model depends on a licensed party holding and delivering the final fiat leg. Removing that party would mean this project would itself need full local banking authorisation, in every destination country it serves.</li></ol><h2 id="what-having-a-partner-actually-requires" tabindex="-1">What &quot;having a partner&quot; actually requires <a class="header-anchor" href="#what-having-a-partner-actually-requires" aria-label="Permalink to &quot;What &quot;having a partner&quot; actually requires&quot;">​</a></h2><p>Not just an API integration. In practice:</p><ul><li>A local banking or e-money licence in the destination country (either held directly by the partner, or through their own correspondent relationship)</li><li>Local currency liquidity to fund payouts before stablecoin settlement is reconciled</li><li>Verification of Payee / Confirmation of Payee capability (or an equivalent), per <a href="./../architecture/payee-verification.html">Payee Verification &amp; Failed Settlement</a></li><li>A KYC/AML programme that satisfies the destination regulator, independent of whatever checks happened upstream</li></ul><p>See <a href="./../business/potential-partners.html">Potential Partners for Collaboration</a> for named candidates by region, and <a href="./../business/partner-coverage.html">Partner Coverage by Corridor</a> for where coverage is confirmed versus still a gap.</p>',8)])])}const y=a(r,[["render",o]]);export{p as __pageData,y as default};
